import{C as n,o as s,c as r,a5 as e,E as a}from"./chunks/framework.URF5zJ_R.js";const c=JSON.parse('{"title":"99 个系统设计核心技能考点矩阵 (Skills Matrix)","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"02_Skills_Matrix.md","filePath":"02_Skills_Matrix.md","lastUpdated":1789005607000}'),g={name:"02_Skills_Matrix.md"},x=Object.assign(g,{setup(i){const l=[{index:"01",title:"CAP 定理与 PACELC 模型",category:"基础理论 · Core",desc:"分布式存储选型的元法则。PACELC 补全了网络正常（Else）下一致性（Consistency）与延迟（Latency）的终极权衡。",meta:{考官切入:"Is this CP or AP?",破局心法:"从网络正常与分区两个维度同时论证"}},{index:"02",title:"分库分表与一致性哈希",category:"数据存储 · Advanced",desc:"突破单库写瓶颈与数据暴涨的核心手段；利用一致性哈希与虚拟节点防止扩缩容时全量数据迁移与热点倾斜。",meta:{考官切入:"How to shard without reshuffling?",破局心法:"重点剖析头部 1% 大 V 热点倾斜兜底"}},{index:"03",title:"Saga 模式与分布式事务",category:"数据存储 · Advanced",desc:"微服务跨库长事务的工业级标准。彻底放弃性能低效且强阻塞的 2PC，通过正向推进与反向补偿动作保证最终一致。",meta:{考官切入:"Payment fails after order placed?",破局心法:"编排式 (Orchestration) 状态机保一致"}},{index:"04",title:"缓存击穿、穿透与雪崩",category:"性能加速 · Advanced",desc:"高并发缓存落地的核心痛点。热点 Key 过期引发瞬间穿透击垮 DB；通过互斥锁排队加载与异步逻辑过期双重护航。",meta:{考官切入:"Hot key expires under 100k QPS?",破局心法:"Mutex 互斥更新 + 随机 TTL 打散"}},{index:"05",title:"读扩散 vs 写扩散 (Fan-out)",category:"核心架构 · Advanced",desc:"社交 Feed 流系统设计的终极分水岭。普通用户走写扩散（Push）；超高粉丝大 V 动态走读扩散（Pull）聚合。",meta:{考官切入:"Design a social feed for 100M MAU",破局心法:"推拉结合混合模型兼顾存储与拉取延迟"}},{index:"06",title:"熔断降级与重试退避",category:"容灾高可用 · Core",desc:"防止单点慢查询耗尽线程池引发微服务级联雪崩。下游过载时必须带随机抖动指数退避，切忌盲目发起重试风暴。",meta:{考官切入:"Downstream P99 latency spikes?",破局心法:"Sentinel/Resilience4j 快速失败"}}];return(o,t)=>{const d=n("CardGrid");return s(),r("div",null,[t[0]||(t[0]=e('<h1 id="_99-个系统设计核心技能考点矩阵-skills-matrix" tabindex="-1">99 个系统设计核心技能考点矩阵 (Skills Matrix) <a class="header-anchor" href="#_99-个系统设计核心技能考点矩阵-skills-matrix" aria-label="Permalink to &quot;99 个系统设计核心技能考点矩阵 (Skills Matrix)&quot;">​</a></h1><blockquote><p><em>涵盖 14 大核心技术门类、99 个核心概念，详述每一个概念在真实高并发场景下的关键价值，以及大厂考官在白板前如何具体切入考核。</em></p></blockquote><hr><div class="tip custom-block"><p class="custom-block-title">💡 架构师备考心法：考官视角不是“背八股”，而是“场景化决策权衡”</p><p>绝大多数候选人在系统设计面试中失利，并不是因为不知道某个开源组件，而是<strong>试图给出一个“绝对完美”的标准答案</strong>。</p><p><strong>资深考官与 Hiring Committee 全程只看重三件事</strong>：</p><ol><li><strong>需求边界厘清（Scoping &amp; Estimation）</strong>：能否在动手画图前先花 5-10 分钟问出吞吐量、读写比、数据保留期与 SLA 约束？</li><li><strong>决策权衡论证（Trade-off Thinking）</strong>：为什么选 X 而不是 Y？引入该组件额外付出了什么网络跳数、一致性或运维复杂度代价？</li><li><strong>单点与容灾兜底（Failure Modes）</strong>：当网络分区、主库宕机或下游响应飙升到 5 秒时，系统会不会发生级联雪崩？有何降级策略？</li></ol></div><hr><h2 id="📊-99-项考点多维全景看板" tabindex="-1">📊 99 项考点多维全景看板 <a class="header-anchor" href="#📊-99-项考点多维全景看板" aria-label="Permalink to &quot;📊 99 项考点多维全景看板&quot;">​</a></h2><p>分布式系统设计体系包含 <strong>14 大知识门类</strong>，涵盖从基础理论、存储通信到可观测性与白板实战：</p><div class="stats-grid" style="margin-bottom:2rem;"><div class="stat-card"><div class="stat-icon">🎯</div><div class="stat-info"><span class="stat-number">99 项</span><span class="stat-label">总高频技能考点</span></div></div><div class="stat-card"><div class="stat-icon">🌱</div><div class="stat-info"><span class="stat-number">10 项 (10%)</span><span class="stat-label">基础筑基 (Foundation)</span></div></div><div class="stat-card"><div class="stat-icon">⚡</div><div class="stat-info"><span class="stat-number">63 项 (64%)</span><span class="stat-label">核心主干 (Core)</span></div></div><div class="stat-card"><div class="stat-icon">🔥</div><div class="stat-info"><span class="stat-number">26 项 (26%)</span><span class="stat-label">进阶突围 (Advanced)</span></div></div><div class="stat-card"><div class="stat-icon">🏛️</div><div class="stat-info"><span class="stat-number">14 门类</span><span class="stat-label">全技术栈覆盖</span></div></div></div><h3 id="🗂️-14-大核心知识门类分布" tabindex="-1">🗂️ 14 大核心知识门类分布 <a class="header-anchor" href="#🗂️-14-大核心知识门类分布" aria-label="Permalink to &quot;🗂️ 14 大核心知识门类分布&quot;">​</a></h3><ul><li>🏗️ <strong>架构与基础 (19项)</strong>：基础理论 (9) · 核心架构 (10)</li><li>🌐 <strong>网络与分发 (12项)</strong>：网络通信 (7) · 负载均衡 (5)</li><li>💾 <strong>存储与缓存 (23项)</strong>：数据存储 (14) · 缓存体系 (6) · 海量存储 (3)</li><li>📨 <strong>异步与消息 (8项)</strong>：消息队列 (8)</li><li>🛡️ <strong>韧性与安全 (14项)</strong>：容灾高可用 (8) · 安全合规 (6)</li><li>📊 <strong>观测与性能 (10项)</strong>：可观测性 (5) · 性能调优 (5)</li><li>💻 <strong>底层与实战 (13项)</strong>：底层设计 LLD (7) · 面试实战 (6)</li></ul><hr><h2 id="🌟-6-大高频架构核心考题精粹" tabindex="-1">🌟 6 大高频架构核心考题精粹 <a class="header-anchor" href="#🌟-6-大高频架构核心考题精粹" aria-label="Permalink to &quot;🌟 6 大高频架构核心考题精粹&quot;">​</a></h2><p>在大厂面试中，以下 6 个核心考点不仅出现频次最高，而且最容易区分候选人是“背诵概念”还是“具备真实工业落地深度”：</p>',13)),a(d,{items:l,columns:3}),t[1]||(t[1]=e('<hr><h2 id="📋-99-个系统设计技能全景对照表" tabindex="-1">📋 99 个系统设计技能全景对照表 <a class="header-anchor" href="#📋-99-个系统设计技能全景对照表" aria-label="Permalink to &quot;📋 99 个系统设计技能全景对照表&quot;">​</a></h2><p>支持表格内<strong>实时搜索过滤</strong>（如输入 <code>Kafka</code>、<code>分布式</code>、<code>缓存</code>、<code>Advanced</code> 即刻筛选），在窄屏移动设备上将自动折叠为流式卡片：</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">知识门类</th><th style="text-align:left;">核心概念 / 技能点</th><th style="text-align:center;">难度</th><th style="text-align:left;">为什么关键 (Why it matters)</th><th style="text-align:left;">面试考核切入点 (How it shows up)</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>基础理论</strong> (Fundamentals)</td><td style="text-align:left;"><strong>垂直扩展 vs 水平扩展 (Vertical vs Horizontal)</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">所有分布式系统设计讨论的第一个分水岭，决定了系统的扩展上限与演进成本复杂度。</td><td style="text-align:left;">&#39;系统在单机上跑得很好，现在流量暴涨 10 倍，你该如何改造？&#39;</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>基础理论</strong> (Fundamentals)</td><td style="text-align:left;"><strong>延迟 vs 吞吐量 (Latency vs Throughput)</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">初学者极易混淆的两个核心指标：单次响应耗时与单位时间处理请求总量，优化策略往往相互制约。</td><td style="text-align:left;">&#39;在当前系统瓶颈下，你优先优化延迟还是吞吐量？为什么两者的调优手段可能冲突？&#39;</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>基础理论</strong> (Fundamentals)</td><td style="text-align:left;"><strong>可用性、可靠性与持久性 (Availability, Reliability, Durability)</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">三种截然不同的 SLA 质量保障，背后代表着呈指数级上升的跨机房多副本基础设施成本。</td><td style="text-align:left;">&#39;业务方要求达到 99.999%（5个9）的可用性，在实际工程中意味着允许多少宕机时间？需要多大代价？&#39;</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>基础理论</strong> (Fundamentals)</td><td style="text-align:left;"><strong>CAP 定理与 PACELC 模型</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">分布式数据存储选型的理论框架；PACELC 进一步补充了网络正常时的延时（Latency）与一致性（Consistency）权衡。</td><td style="text-align:left;">&#39;你设计的这个存储子系统是 CP 还是 AP？给出你的业务论据与分区恢复策略。&#39;</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>基础理论</strong> (Fundamentals)</td><td style="text-align:left;"><strong>一致性模型 (强一致、最终一致、因果一致)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">决定了用户和下游服务在并发读写时能观察到什么数据状态，直接决定了系统架构的复杂度与吞吐极限。</td><td style="text-align:left;">&#39;用户发布了一条动态，刷新后自己看不到，这在当前业务场景中是否可以接受？为什么？&#39;</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>基础理论</strong> (Fundamentals)</td><td style="text-align:left;"><strong>数量级与费米估算 (Back-of-the-Envelope Estimation)</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">系统设计面试开场前 5 分钟的核心环节，直接决定了单机还是分布式、选什么数据库与估算机器成本。</td><td style="text-align:left;">&#39;根据当前 DAU、每人发帖频次与图片大小，估算该系统每年需要多少存储容量和写 QPS？&#39;</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>基础理论</strong> (Fundamentals)</td><td style="text-align:left;"><strong>功能性需求 vs 非功能性需求 (Functional vs Non-Functional)</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">设计前先厘清需求边界是拿高分的最重要习惯，盲目直接画架构图往往会导致严重跑偏或过度设计。</td><td style="text-align:left;">考官全程观察你是在拿到题目后先澄清需求约束，还是不假思索直接开始堆砌组件。</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>基础理论</strong> (Fundamentals)</td><td style="text-align:left;"><strong>单点故障 (Single Points of Failure - SPOF)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">高可用架构的死穴，在架构拓扑图上画出的每一个未经冗余的主节点或代理，都是潜在的灾难策源地。</td><td style="text-align:left;">&#39;如果架构图中的这台单主数据库或网关节点突发断电挂掉，整个系统会发生什么？&#39;</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>基础理论</strong> (Fundamentals)</td><td style="text-align:left;"><strong>架构权衡思维 (Trade-off Thinking)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">工程领域不存在完美的银弹架构，只有权衡取舍后最契合当下业务阶段与成本约束的技术方案。</td><td style="text-align:left;">整场架构面试的终极考察点：考官会不断质疑你的组件选型，看你如何用 Trade-off 论证合理性。</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;"><strong>网络通信</strong> (Networking)</td><td style="text-align:left;"><strong>DNS 解析与全局流量路由</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">用户流量进入系统的第一站入口，依托 Anycast 与 GeoDNS 实现就近接入与多机房跨地域容灾调度。</td><td style="text-align:left;">&#39;请详述从用户在浏览器按下回车，到请求抵达你的 API 网关之前，网络链路究竟经历了哪些步骤？&#39;</td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><strong>网络通信</strong> (Networking)</td><td style="text-align:left;"><strong>HTTP, HTTPS 与 TLS 握手</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">绝大多数网络系统设计的应用层协议基石，TLS 握手延迟对首次建连性能和安全至关重要。</td><td style="text-align:left;">&#39;TLS 握手在你的架构中的哪一层终结（卸载）？卸载后内部微服务通信如何保证安全？&#39;</td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;"><strong>网络通信</strong> (Networking)</td><td style="text-align:left;"><strong>TCP vs UDP 协议选型</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">音视频通话、实时电竞、海量埋点监控与金融交易系统在可靠性、队头阻塞与延迟之间的根本取舍。</td><td style="text-align:left;">&#39;为什么在这个位置你会选用基于 UDP 的 QUIC/HTTP3，而不是传统的 TCP 协议？&#39;</td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><strong>网络通信</strong> (Networking)</td><td style="text-align:left;"><strong>WebSockets, 长轮询 (Long Polling) 与 SSE</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">实时双向协作（在线聊天、协作文档、股票行情）必备，协议开销、长连接维持与状态管理差异巨大。</td><td style="text-align:left;">&#39;当群聊有新消息到达时，客户端如何获知？三种实时推送方案各有什么优缺点？&#39;</td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;"><strong>网络通信</strong> (Networking)</td><td style="text-align:left;"><strong>gRPC 与 Protocol Buffers 二进制传输</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">超大规模微服务集群内部东西向流量的标准协议，多路复用与高效紧凑二进制序列化大幅节省带宽与 CPU。</td><td style="text-align:left;">&#39;内部微服务之间的通信，什么时候选 REST/JSON？什么时候必须切换到 gRPC/Protobuf？&#39;</td></tr><tr><td style="text-align:center;">15</td><td style="text-align:left;"><strong>网络通信</strong> (Networking)</td><td style="text-align:left;"><strong>CDN 内容分发网络与边缘缓存</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">静态资源、高频点播视频与边缘计算加速核心，将 95% 以上带宽流量拦截在源站机房之外。</td><td style="text-align:left;">&#39;澳大利亚的用户打开北美机房的页面加载需要 3 秒，请给出完整的加速改造方案。&#39;</td></tr><tr><td style="text-align:center;">16</td><td style="text-align:left;"><strong>网络通信</strong> (Networking)</td><td style="text-align:left;"><strong>代理架构：正向代理、反向代理与 API Gateway</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">流量入口的守门人，承载统一身份鉴权、动态服务路由、全局速率限制与协议适配转换。</td><td style="text-align:left;">&#39;用户身份认证与 JWT 解析具体在架构的哪一层完成？网关还是下游业务微服务？&#39;</td></tr><tr><td style="text-align:center;">17</td><td style="text-align:left;"><strong>负载均衡</strong> (Load Balancing)</td><td style="text-align:left;"><strong>负载均衡器类型与多层级部署拓扑</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">横向扩展架构不可或缺的核心枢纽，避免单机过载，实现无状态计算节点的弹性水平扩缩容。</td><td style="text-align:left;">&#39;在你的架构图中，负载均衡器放了几层？分别部署在哪些节点之间？&#39;</td></tr><tr><td style="text-align:center;">18</td><td style="text-align:left;"><strong>负载均衡</strong> (Load Balancing)</td><td style="text-align:left;"><strong>分流算法 (轮询、加权最小连接、一致性哈希)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">算法直接决定各节点的资源利用率、热点分布以及有状态服务和缓存节点的命中率。</td><td style="text-align:left;">&#39;在当前服务场景中，为什么选用一致性哈希分流，而不是简单的轮询（Round Robin）？&#39;</td></tr><tr><td style="text-align:center;">19</td><td style="text-align:left;"><strong>负载均衡</strong> (Load Balancing)</td><td style="text-align:left;"><strong>四层 (L4) vs 七层 (L7) 负载均衡</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">基于传输层 IP/端口的高性能包转发 vs 基于应用层 HTTP 路径、Header、Cookie 的智能化业务路由。</td><td style="text-align:left;">&#39;L7 负载均衡器能实现哪些 L4 负载均衡器完全无法做到的路由和安全治理能力？&#39;</td></tr><tr><td style="text-align:center;">20</td><td style="text-align:left;"><strong>负载均衡</strong> (Load Balancing)</td><td style="text-align:left;"><strong>健康检查机制与自动故障转移 (Failover)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">自动将宕机或亚健康（高延迟）节点踢出路由池，防止故障扩散，确保对外 SLA 稳定。</td><td style="text-align:left;">&#39;当一台业务服务器由于内存溢出（OOM）卡死时，负载均衡器如何及时停止向其转发流量？&#39;</td></tr><tr><td style="text-align:center;">21</td><td style="text-align:left;"><strong>负载均衡</strong> (Load Balancing)</td><td style="text-align:left;"><strong>粘性会话 (Sticky Sessions) 及其隐患</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">无状态是水平扩展的前提；粘性会话破坏了弹性伸缩、增加了单点雪崩风险与负载不均。</td><td style="text-align:left;">&#39;为什么在现代大规模微服务架构中，极力反对在应用节点本地内存中保存 Session 状态？&#39;</td></tr><tr><td style="text-align:center;">22</td><td style="text-align:left;"><strong>缓存体系</strong> (Caching)</td><td style="text-align:left;"><strong>缓存读写策略 (Cache-Aside, Write-Through, Write-Back)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">决定了缓存与底层数据库之间的一致性保障、写入延迟与在节点崩溃时的数据丢失风险。</td><td style="text-align:left;">&#39;你的系统选用哪种缓存策略？当数据库写成功但缓存删失败时，如何应对脏读？&#39;</td></tr><tr><td style="text-align:center;">23</td><td style="text-align:left;"><strong>缓存体系</strong> (Caching)</td><td style="text-align:left;"><strong>缓存淘汰算法 (LRU, LFU, FIFO, TTL)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">内存容量始终有限，合理的淘汰算法能在内存打满时以最高效率剔除冷数据、保全热点高频数据。</td><td style="text-align:left;">&#39;请手写或描述 LRU 缓存的核心数据结构原理（哈希表 + 双向链表）。&#39;</td></tr><tr><td style="text-align:center;">24</td><td style="text-align:left;"><strong>缓存体系</strong> (Caching)</td><td style="text-align:left;"><strong>缓存失效与双写一致性 (Cache Invalidation)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">计算机科学领域最著名的两大难题之一；在高并发并发更新时如何避免脏数据长期驻留。</td><td style="text-align:left;">&#39;数据库行记录发生变更，缓存应该‘更新’还是‘删除’？延时双删或 Canal 监听 Binlog 怎么做？&#39;</td></tr><tr><td style="text-align:center;">25</td><td style="text-align:left;"><strong>缓存体系</strong> (Caching)</td><td style="text-align:left;"><strong>Redis vs Memcached 架构选型与内核差异</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">业界最主流的两大分布式缓存方案；丰富数据结构、单线程事件驱动/多线程、集群分片与持久化支持差异。</td><td style="text-align:left;">&#39;为什么选 Redis 而不是 Memcached？两者在多线程模型与内存分配机制上有何本质差异？&#39;</td></tr><tr><td style="text-align:center;">26</td><td style="text-align:left;"><strong>缓存体系</strong> (Caching)</td><td style="text-align:left;"><strong>多级缓存架构 (Browser, CDN, Gateway, In-Process, Redis)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">高性能高并发架构绝非只靠一层 Redis，合理的逐级漏斗设计让 99% 的请求在抵达数据库前被消化。</td><td style="text-align:left;">&#39;绘制当前架构的多级缓存布局图，哪一层拦截了多少百分比的流量？&#39;</td></tr><tr><td style="text-align:center;">27</td><td style="text-align:left;"><strong>缓存体系</strong> (Caching)</td><td style="text-align:left;"><strong>缓存穿透、击穿与雪崩 (Thundering Herd / Stampede)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">生产环境热点 Key 过期或突发未命中导致数万 QPS 直击后端数据库引发整体宕机的经典死穴。</td><td style="text-align:left;">&#39;一个拥有 1000 万热度的大 V 发帖，缓存过期瞬间数据库瞬间被打趴下，如何从架构层面彻底杜绝？&#39;</td></tr><tr><td style="text-align:center;">28</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>SQL vs NoSQL 选型决策树</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">继扩展性之后面试最常见的选择题：强事务/复杂 Join 关系型 vs 海量高频吞吐/水平扩容 NoSQL。</td><td style="text-align:left;">&#39;针对该功能，你选用 PostgreSQL 还是 Cassandra？给出充分的对比与业务论据。&#39;</td></tr><tr><td style="text-align:center;">29</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>关系建模与范式化 vs 反范式化 (Normalisation vs Denormalisation)</strong></td><td style="text-align:center;"><code>Foundation</code></td><td style="text-align:left;">数据库 Schema 是一旦上线最难且变更成本最高的资产；读性能优化与写一致性冗余的经典取舍。</td><td style="text-align:left;">&#39;请为该系统设计核心数据库表结构，包含哪些字段与索引？是否有冗余字段？为什么？&#39;</td></tr><tr><td style="text-align:center;">30</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>索引底层原理与慢查询优化 (B+Tree, Hash, LSM)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">区分毫秒级极速响应与数秒慢查导致连接池占满的核心技能；覆盖索引、最左前缀与回表代价。</td><td style="text-align:left;">&#39;海量数据下这个 SQL 查询非常缓慢，你会如何分析执行计划（EXPLAIN）并建立最优索引？&#39;</td></tr><tr><td style="text-align:center;">31</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>主从复制架构 (Leader-Follower, Multi-Leader, Leaderless)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">读写分离扩展读吞吐量与灾难恢复基石；异步复制、半同步复制与无主写入（Quorum）机制。</td><td style="text-align:left;">&#39;如何扩展读性能？从库数量能无限增加吗？主从复制延迟会引发什么业务问题？&#39;</td></tr><tr><td style="text-align:center;">32</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>主从复制延迟与写后读一致性 (Read-Your-Writes Consistency)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">用户更新个人资料或发表评论后刷新页面却显示旧数据的根源；关键业务路径的读主路由方案。</td><td style="text-align:left;">&#39;用户刚修改了密码或扣减了余额，马上跳转详情页，如何保证该请求绝对不会读到旧从库？&#39;</td></tr><tr><td style="text-align:center;">33</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>分库分表与水平分区策略 (Sharding &amp; Partitioning)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">单表数据破千万/亿级与单库写入 I/O 达到物理上限后的必经之路；分区键（Partition Key）选型核心。</td><td style="text-align:left;">&#39;如果按 user_id 分片，如何高效支持基于 order_time 或 status 的非分区键分页查询？&#39;</td></tr><tr><td style="text-align:center;">34</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>一致性哈希与虚拟节点 (Consistent Hashing)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">在动态增加或下线存储节点时，避免传统模运算导致全量数据大范围重哈希与数据搬迁雪崩。</td><td style="text-align:left;">&#39;新增两台存储节点，如何做到只迁移极少量局部数据？虚拟节点如何解决数据倾斜问题？&#39;</td></tr><tr><td style="text-align:center;">35</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>热点分区与数据倾斜 (Hot Partitions &amp; Skew)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">头部 1% 的超级大 V（如马斯克、明星账号）可能以一己之力打爆单个分库或分片物理机的性能上限。</td><td style="text-align:left;">&#39;如果以主播 ID 为分区键，顶级带货主播直播时单个分片 QPS 暴涨 100 倍，该如何兜底设计？&#39;</td></tr><tr><td style="text-align:center;">36</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>ACID 事务与并发隔离级别 (Isolation Levels)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">资金交易、秒杀库存扣减绝对正确性的理论保证；读已提交、可重复读与幻读/死锁防控。</td><td style="text-align:left;">&#39;两个用户同时并发购买最后一件库存商品，在数据库层面如何防止超卖？悲观锁还是乐观锁？&#39;</td></tr><tr><td style="text-align:center;">37</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>分布式事务与两阶段提交 (2PC / 3PC)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">微服务跨数据库一致性的经典理论，理解为什么工业界大规模高吞吐系统极力避免阻塞式 2PC。</td><td style="text-align:left;">&#39;在两个微服务各自独立的数据库之间，如何实现跨库转账事务？为什么不建议用 XA/2PC？&#39;</td></tr><tr><td style="text-align:center;">38</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>Saga 模式与补偿事务 (Compensating Transactions)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">分布式微服务长事务的工业界最实用落地标准；通过协同式（Choreography）或编排式（Orchestration）推进。</td><td style="text-align:left;">&#39;电商下单成功扣了库存，但随后的支付渠道扣款失败超时，Saga 状态机如何执行反向补偿流程？&#39;</td></tr><tr><td style="text-align:center;">39</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>NoSQL 四大主流技术家族 (KV, Document, Wide-Column, Graph)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">四大体系（如 Redis、MongoDB、Cassandra、Neo4j）在底层存储引擎与访问模式上存在本质差异。</td><td style="text-align:left;">&#39;针对社交好友关系链推荐，与针对海量物联网传感器日志，分别选哪类 NoSQL？为什么？&#39;</td></tr><tr><td style="text-align:center;">40</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>时序数据库 (TSDB) 与 OLAP 分析型数据库 (ClickHouse, Snowflake)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">列式存储、高效压缩算法与并行扫描引擎，为万亿级日志监控与复杂多维实时报表提供秒级响应。</td><td style="text-align:left;">&#39;每天需要写入 20 亿条埋点日志并支持任意维度的多聚合统计，选用哪种存储引擎最省成本？&#39;</td></tr><tr><td style="text-align:center;">41</td><td style="text-align:left;"><strong>数据存储</strong> (Databases)</td><td style="text-align:left;"><strong>数据库连接池与连接风暴 (Connection Pooling)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">线上应用突发流量导致数据库直连数跑满、操作系统频繁上下文切换与拒绝服务的经典生产故障。</td><td style="text-align:left;">&#39;微服务集群弹性扩容到 500 个实例，数据库直接报错拒绝连接，从架构层面如何解决？&#39;</td></tr><tr><td style="text-align:center;">42</td><td style="text-align:left;"><strong>海量存储</strong> (Storage)</td><td style="text-align:left;"><strong>对象存储 vs 块存储 vs 文件存储 (Object vs Block vs File)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">海量非结构化资产（图片、视频、备份）与操作系统持久盘（EBS、本地 NVMe）在成本与访问协议上的巨大差异。</td><td style="text-align:left;">&#39;用户上传的高清视频和头像图片，应该保存在哪种存储介质？为什么不能直接存应用服务器磁盘？&#39;</td></tr><tr><td style="text-align:center;">43</td><td style="text-align:left;"><strong>海量存储</strong> (Storage)</td><td style="text-align:left;"><strong>对象存储预签名直传 (Presigned URLs)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">将 GB 级大文件流量彻底从业务网关和后端服务器卸载，极大节省服务器网络出入带宽与内存开销。</td><td style="text-align:left;">&#39;客户端上传一个 2GB 的大视频文件，如何设计直传通路，避免字节流打爆后端业务节点？&#39;</td></tr><tr><td style="text-align:center;">44</td><td style="text-align:left;"><strong>海量存储</strong> (Storage)</td><td style="text-align:left;"><strong>数据生命周期、分层存储与冷热归档 (Tiering &amp; Archival)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">控制企业海量数据云上存储成本的关键：热数据 SSD、温数据标准对象存储、冷数据归档磁带存储。</td><td style="text-align:left;">&#39;系统每月新增 40TB 数据，如何制定生命周期策略，保证系统运行到第 3 年时成本依然可控？&#39;</td></tr><tr><td style="text-align:center;">45</td><td style="text-align:left;"><strong>消息队列</strong> (Messaging)</td><td style="text-align:left;"><strong>消息队列核心价值 (解耦、削峰填谷、异步缓冲)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">防止下游慢服务（如邮件/短信、积分计算）拖慢核心交易主链路；将瞬时脉冲流量平滑转化为匀速消费。</td><td style="text-align:left;">&#39;用户下单时如果第三方邮件通知服务响应缓慢，如何通过消息队列改造保证主流程秒级返回？&#39;</td></tr><tr><td style="text-align:center;">46</td><td style="text-align:left;"><strong>消息队列</strong> (Messaging)</td><td style="text-align:left;"><strong>Apache Kafka 与基于日志分区的流存储</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">现代海量事件流架构的默认骨干中枢；分区日志存储、消费者组（Consumer Group）与零拷贝极速读写。</td><td style="text-align:left;">&#39;详述 Kafka 的 Partition 分区机制与 Consumer Group 是如何协同实现高并发水平扩展的？&#39;</td></tr><tr><td style="text-align:center;">47</td><td style="text-align:left;"><strong>消息队列</strong> (Messaging)</td><td style="text-align:left;"><strong>RabbitMQ, SQS 与传统消息代理差异</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">灵活的路由键与 Exchange 拓扑 vs 简单的分布式任务队列；消息消费确认与存储模型本质差异。</td><td style="text-align:left;">&#39;在当前场景下选 Kafka 还是 RabbitMQ/SQS？两者的消费模型（Push vs Pull）有什么不同？&#39;</td></tr><tr><td style="text-align:center;">48</td><td style="text-align:left;"><strong>消息队列</strong> (Messaging)</td><td style="text-align:left;"><strong>发布/订阅 (Pub/Sub) vs 点对点队列 (Point-to-Point)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">单播分发给单一工作者 vs 广播通知多个下游独立微服务（订单完成同时触发库存、积分、风控）。</td><td style="text-align:left;">&#39;当下游有五个异构服务都需要捕获用户注销事件时，消息拓扑应该如何设计？&#39;</td></tr><tr><td style="text-align:center;">49</td><td style="text-align:left;"><strong>消息队列</strong> (Messaging)</td><td style="text-align:left;"><strong>消息投递语义 (最多一次、至少一次、精确一次)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">分布式网络重试下‘精确一次’（Exactly-Once）的巨大工程挑战；理解为什么多数系统基于至少一次 + 业务幂等实现。</td><td style="text-align:left;">&#39;端到端的 Exactly-Once 究竟有多难实现？Kafka 的事务消息与下游消费端如何配合？&#39;</td></tr><tr><td style="text-align:center;">50</td><td style="text-align:left;"><strong>消息队列</strong> (Messaging)</td><td style="text-align:left;"><strong>幂等性保障与重复消息去重 (Idempotency &amp; Deduplication)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">分布式网络丢包重试是必然的，重复扣费或重复发货是绝对不可容忍的；唯一业务流水号与幂等表设计。</td><td style="text-align:left;">&#39;支付成功 Webhook 回调因为网络抖动连续触发了两次，你的消费逻辑如何确保绝对不会重复入账？&#39;</td></tr><tr><td style="text-align:center;">51</td><td style="text-align:left;"><strong>消息队列</strong> (Messaging)</td><td style="text-align:left;"><strong>死信队列 (DLQ) 与毒药消息处理 (Poison Messages)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">格式畸形或引发代码逻辑死循环崩溃的消息可能导致整个分区消费者阻塞挂起；重试次数与告警机制。</td><td style="text-align:left;">&#39;一条消息消费总是抛出异常导致重试死循环，如何隔离并不影响后续成千上万条正常消息的消费？&#39;</td></tr><tr><td style="text-align:center;">52</td><td style="text-align:left;"><strong>消息队列</strong> (Messaging)</td><td style="text-align:left;"><strong>事件驱动架构 (EDA) 与事件溯源 (Event Sourcing)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">完全解耦的异步响应系统与具备完整历史审计追踪能力的状态存储模式；CQRS 读写分离架构。</td><td style="text-align:left;">&#39;事件溯源（Event Sourcing）为你带来了什么核心收益？在数据重放与快照重建上需要付出什么代价？&#39;</td></tr><tr><td style="text-align:center;">53</td><td style="text-align:left;"><strong>核心架构</strong> (Architecture)</td><td style="text-align:left;"><strong>单体架构 vs 微服务演进之路 (Monolith vs Microservices)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">绝大多数新系统初期的最佳选择其实是结构清晰的单体；过早微服务化会引入毁灭性的运维与网络成本。</td><td style="text-align:left;">&#39;我们是否应该把这个系统拆分为微服务？通常答案是否定的，请给出你的架构演进论证。&#39;</td></tr><tr><td style="text-align:center;">54</td><td style="text-align:left;"><strong>核心架构</strong> (Architecture)</td><td style="text-align:left;"><strong>服务边界划分与领域驱动设计 (DDD Bounded Context)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">微服务架构中最艰难的是‘在哪里切刀’，不合理的切分会导致分布式单体（Distributed Monolith）与网状依赖噩梦。</td><td style="text-align:left;">&#39;你如何根据业务领域模型界定上下文边界，将整个系统科学切分为独立部署的服务模块？&#39;</td></tr><tr><td style="text-align:center;">55</td><td style="text-align:left;"><strong>核心架构</strong> (Architecture)</td><td style="text-align:left;"><strong>API 协议契约设计 (RESTful vs GraphQL vs gRPC)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">系统组件之间交互的契约；按需字段拉取（避免 Over-fetching）、强类型代码生成与传输效率权衡。</td><td style="text-align:left;">&#39;客户端界面经常变更且存在过度获取数据问题，为什么考虑 GraphQL？它在缓存层面有什么硬伤？&#39;</td></tr><tr><td style="text-align:center;">56</td><td style="text-align:left;"><strong>核心架构</strong> (Architecture)</td><td style="text-align:left;"><strong>API 网关与 BFF 架构 (Backend for Frontend)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">针对 Web、iOS、Android 不同客户端定制数据聚合接口，避免前端与数十个底层微服务产生紧耦合。</td><td style="text-align:left;">&#39;当系统有 12 个底层微服务和 3 种异构终端（App、Web、小程序）时，如何设计统一入口与数据组装？&#39;</td></tr><tr><td style="text-align:center;">57</td><td style="text-align:left;"><strong>核心架构</strong> (Architecture)</td><td style="text-align:left;"><strong>服务发现与 Service Mesh 服务网格</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">动态容器云环境下微服务 IP 频繁漂移的动态寻址；Sidecar 代理无侵入接管微服务流量治理与 mTLS 加密。</td><td style="text-align:left;">&#39;服务 A 在没有硬编码 IP 的情况下，如何动态感知并负载均衡调用服务 B 的数十个健康实例？&#39;</td></tr><tr><td style="text-align:center;">58</td><td style="text-align:left;"><strong>核心架构</strong> (Architecture)</td><td style="text-align:left;"><strong>无状态服务与状态外置原则 (Stateless Services)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">应用节点无状态化是实现秒级弹性伸缩（HPA）与故障随时替换的绝对先决条件。</td><td style="text-align:left;">&#39;为什么说应用实例必须做到完全无状态？用户状态、Session 与临时文件应该如何正确外置存储？&#39;</td></tr><tr><td style="text-align:center;">59</td><td style="text-align:left;"><strong>核心架构</strong> (Architecture)</td><td style="text-align:left;"><strong>读密集型 vs 写密集型架构特征差异</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">读写比（如 1000:1 vs 1:10）是决定架构路线的根本罗盘；多级缓存拓扑 vs 顺序写追加日志与批量落盘。</td><td style="text-align:left;">&#39;如果业务特征是 1000:1 的极端读多写少，架构设计上与写密集型系统有何根本不同？&#39;</td></tr><tr><td style="text-align:center;">60</td><td style="text-align:left;"><strong>核心架构</strong> (Architecture)</td><td style="text-align:left;"><strong>读扩散 (Fan-out on Read) vs 写扩散 (Fan-out on Write)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">社交动态 Feed 流（Twitter/微博）系统设计的终极取舍；明星大 V 发帖的写扩散灾难与混合推拉模型。</td><td style="text-align:left;">&#39;设计一个亿级用户的社交 Timeline：为什么不能简单对所有用户采用写扩散（Push）方案？&#39;</td></tr><tr><td style="text-align:center;">61</td><td style="text-align:left;"><strong>核心架构</strong> (Architecture)</td><td style="text-align:left;"><strong>多地域部署与异地多活 (Multi-Region &amp; Geo-Distribution)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">光速物理延迟与单地域断缆灾难；单元化架构、跨机房复制延迟与冲突解决策略（CRDT）。</td><td style="text-align:left;">&#39;用户分布在亚欧美三大洲，如何在提供毫秒级本地低延迟读写的同时，防范单机房整体瘫痪？&#39;</td></tr><tr><td style="text-align:center;">62</td><td style="text-align:left;"><strong>核心架构</strong> (Architecture)</td><td style="text-align:left;"><strong>Lambda 架构 vs Kappa 架构</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">大数据流批一体设计的两种演进哲学；维护双重代码库（Batch + Speed）还是全流式统一存储与计算。</td><td style="text-align:left;">&#39;你的实时指标统计系统是否需要维护批处理层？Kappa 架构在历史数据重算时怎么处理？&#39;</td></tr><tr><td style="text-align:center;">63</td><td style="text-align:left;"><strong>容灾高可用</strong> (Reliability)</td><td style="text-align:left;"><strong>高可用冗余与主备故障切换 (Redundancy &amp; Failover)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">高可用最质朴的原则：每一个核心组件都必须有随时可接替的备用实例，杜绝单点崩溃。</td><td style="text-align:left;">&#39;主数据库节点突发死机，从库如何自动提升为主库（Promotion）？脑裂（Split-Brain）如何防范？&#39;</td></tr><tr><td style="text-align:center;">64</td><td style="text-align:left;"><strong>容灾高可用</strong> (Reliability)</td><td style="text-align:left;"><strong>熔断器、重试风暴与指数退避 (Circuit Breaker &amp; Backoff)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">防止下游慢调用耗尽上游线程池引发级联雪崩；重试必须加入随机抖动（Jitter），禁止盲目并发重试。</td><td style="text-align:left;">&#39;下游服务响应时间从 10ms 飙升至 5s，你的服务调用方会发生什么？如何通过熔断器自保？&#39;</td></tr><tr><td style="text-align:center;">65</td><td style="text-align:left;"><strong>容灾高可用</strong> (Reliability)</td><td style="text-align:left;"><strong>超时控制与舱壁隔离 (Timeouts &amp; Bulkheads)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">将故障严格局限在单一线程池或隔离区，防止一个次要业务（如评论加载）拖垮核心支付交易主链。</td><td style="text-align:left;">&#39;如何防止一个慢依赖耗尽容器的所有工作线程？超时时间设置过长或过短分别有什么危害？&#39;</td></tr><tr><td style="text-align:center;">66</td><td style="text-align:left;"><strong>容灾高可用</strong> (Reliability)</td><td style="text-align:left;"><strong>限流与节流算法 (Token Bucket, Leaky Bucket, Sliding Window)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">保护系统容量不被超出预期的洪峰打垮，保证对合法用户的公平性与系统底层防御安全。</td><td style="text-align:left;">&#39;请详细对比令牌桶与漏桶算法的差异，并设计一个基于 Redis 的分布式滑动窗口限流器。&#39;</td></tr><tr><td style="text-align:center;">67</td><td style="text-align:left;"><strong>容灾高可用</strong> (Reliability)</td><td style="text-align:left;"><strong>优雅降级与过载保护 (Graceful Degradation &amp; Load Shedding)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">在系统濒临过载崩溃时，舍车保帅，主动关闭次要功能（如千人千面个性化推荐），确保核心链路可用。</td><td style="text-align:left;">&#39;突发流量达到平时预估的 5 倍，系统即将整体 OOM，你会按什么优先级主动关闭哪些业务模块？&#39;</td></tr><tr><td style="text-align:center;">68</td><td style="text-align:left;"><strong>容灾高可用</strong> (Reliability)</td><td style="text-align:left;"><strong>背压机制 (Backpressure)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">下游消费者处理不过来时主动通知上游生产端降低发送速率，防止本地内存队列无限膨胀导致崩溃。</td><td style="text-align:left;">&#39;当消息消费端处理速度赶不上生产端发送速率时，除了扩容机器，系统如何实施背压控制？&#39;</td></tr><tr><td style="text-align:center;">69</td><td style="text-align:left;"><strong>容灾高可用</strong> (Reliability)</td><td style="text-align:left;"><strong>容灾指标 RTO 与 RPO (Recovery Time &amp; Point Objective)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">业务对灾难发生时‘能容忍停机多久’与‘能容忍丢失多少数据’的量化指标，决定了容灾备份的投资上限。</td><td style="text-align:left;">&#39;某个可用区（AZ）发生断网灾难，你的系统恢复正常需要多久（RTO）？最多可能丢失几分钟数据（RPO）？&#39;</td></tr><tr><td style="text-align:center;">70</td><td style="text-align:left;"><strong>容灾高可用</strong> (Reliability)</td><td style="text-align:left;"><strong>混沌工程与故障演练 (Chaos Engineering)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">在生产环境中主动注入故障（杀节点、拔网线、模拟高延迟），证明系统的韧性而不是盲目盲信理论设计。</td><td style="text-align:left;">&#39;你如何向管理层证明你设计的数据库双机热备与主备切换方案在半夜真正出事时真的能生效？&#39;</td></tr><tr><td style="text-align:center;">71</td><td style="text-align:left;"><strong>可观测性</strong> (Observability)</td><td style="text-align:left;"><strong>可观测三大支柱 (Logs, Metrics, Traces)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">系统运行状况的透视镜：结构化事件日志（Logs）、数值聚合度量（Metrics）与请求全链路流转（Traces）。</td><td style="text-align:left;">&#39;当线上一个用户请求跨越了 8 个微服务且返回极慢时，你如何利用可观测体系定位瓶颈所在？&#39;</td></tr><tr><td style="text-align:center;">72</td><td style="text-align:left;"><strong>可观测性</strong> (Observability)</td><td style="text-align:left;"><strong>分布式链路追踪与 Correlation ID (TraceContext)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">在微服务网状调用中串联单一业务请求的生命周期；基于 OpenTelemetry 标准跨进程透传 TraceID。</td><td style="text-align:left;">&#39;在多服务异步消息调用链路上，Correlation ID 是如何跨 HTTP Header 与 MQ 消息体透明透传的？&#39;</td></tr><tr><td style="text-align:center;">73</td><td style="text-align:left;"><strong>可观测性</strong> (Observability)</td><td style="text-align:left;"><strong>SLI, SLO 与错误预算 (Error Budgets)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">将系统可靠性转化为可量化的业务契约；当错误预算耗尽时冻结新功能发布、全力修复系统稳定性。</td><td style="text-align:left;">&#39;你们团队制定的核心 SLO 是什么？当本季度的错误预算快消耗完毕时，工程研发流程会发生什么变化？&#39;</td></tr><tr><td style="text-align:center;">74</td><td style="text-align:left;"><strong>可观测性</strong> (Observability)</td><td style="text-align:left;"><strong>告警体系与 On-Call 轮值设计</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">告警必须面向影响用户的‘症状’（如错误率突增、P99 超标）而非底层‘原因’（如某台机器 CPU 偏高），杜绝告警疲劳。</td><td style="text-align:left;">&#39;你会为该系统配置哪些直接触发 P0/P1 电话告警的指标？哪些指标只记录在 Dashboard 上不报警？&#39;</td></tr><tr><td style="text-align:center;">75</td><td style="text-align:left;"><strong>可观测性</strong> (Observability)</td><td style="text-align:left;"><strong>存活探针与就绪探针 (Liveness vs Readiness Probes)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">K8s 等容器调度编排系统判断实例是否需要重启（Liveness）还是暂时移出流量分发池（Readiness）的凭据。</td><td style="text-align:left;">&#39;详细说明 Liveness 和 Readiness 探针的本质区别？如果探针接口误查了慢数据库会引发什么灾难？&#39;</td></tr><tr><td style="text-align:center;">76</td><td style="text-align:left;"><strong>安全合规</strong> (Security)</td><td style="text-align:left;"><strong>大规模分布式认证与鉴权 (Authentication &amp; Authorisation)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">任何线上系统的第一道安全大门：确认‘你是谁’（认证）与‘你能做什么操作’（RBAC / ABAC 授权）。</td><td style="text-align:left;">&#39;在一个包含数十个内部微服务的架构中，下游微服务如何验证用户身份与权限？需要反复查库吗？&#39;</td></tr><tr><td style="text-align:center;">77</td><td style="text-align:left;"><strong>安全合规</strong> (Security)</td><td style="text-align:left;"><strong>OAuth 2.0, OIDC 与 JWT 令牌机制</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">现代互联网三方授权与无状态身份票据事实标准；网关验签、私钥签名公钥验签与令牌吊销难题。</td><td style="text-align:left;">&#39;JWT 令牌一旦签发如何提前主动失效？黑名单机制如何在保持无状态与查询性能之间做权衡？&#39;</td></tr><tr><td style="text-align:center;">78</td><td style="text-align:left;"><strong>安全合规</strong> (Security)</td><td style="text-align:left;"><strong>传输层加密与静态存储加密 (Encryption in Transit &amp; at Rest)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">现代架构的基本安全基线与行业合规强制要求；mTLS 双向认证与敏感数据列级 KMS 密钥信封加密。</td><td style="text-align:left;">&#39;在数据库遭遇黑客拖库攻击后，如何保证用户的密码、身份证号与信用卡数据依然无法被破解？&#39;</td></tr><tr><td style="text-align:center;">79</td><td style="text-align:left;"><strong>安全合规</strong> (Security)</td><td style="text-align:left;"><strong>生产环境密钥与凭据管理 (Secrets Management)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">数据库密码、API Key 严禁硬编码在代码或明文配置文件中；依托 Vault、KMS 实现动态签发与轮换。</td><td style="text-align:left;">&#39;生产环境中的数据库密码和第三方 API Token 存放在哪里？如何在不重启服务的情况下实现平滑轮换？&#39;</td></tr><tr><td style="text-align:center;">80</td><td style="text-align:left;"><strong>安全合规</strong> (Security)</td><td style="text-align:left;"><strong>DDoS 攻击防护与 WAF 应用防火墙</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">在海量恶意流量或恶意爬虫攻击下保全系统可用性；边缘清洗、SYN Flood 防御与 SQL 注入拦截。</td><td style="text-align:left;">&#39;黑客利用僵尸网络对你的登录接口发起每秒数十万次恶意请求，你的整体防御体系如何多层拦截？&#39;</td></tr><tr><td style="text-align:center;">81</td><td style="text-align:left;"><strong>安全合规</strong> (Security)</td><td style="text-align:left;"><strong>数据隐私合规 (GDPR, 数据本地化出境法规)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">合规重塑架构：欧盟 GDPR‘被遗忘权’与跨国企业数据必须留在本国物理机房的法定义务。</td><td style="text-align:left;">&#39;当用户行使 GDPR‘被遗忘权’申请注销所有个人数据时，如何彻底清理分布在主库、日志与多级备份中的数据？&#39;</td></tr><tr><td style="text-align:center;">82</td><td style="text-align:left;"><strong>性能调优</strong> (Performance)</td><td style="text-align:left;"><strong>容量规划与全链路压测 (Capacity Planning &amp; Load Testing)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">在真实用户流量压垮系统之前先摸清系统的极限与水位瓶颈；利用单机基准测试推导全集群硬件规模需求。</td><td style="text-align:left;">&#39;支撑 10 万并发在线用户发帖，需要多少台 8C16G 应用服务器和多大数据库规格？写出推算过程。&#39;</td></tr><tr><td style="text-align:center;">83</td><td style="text-align:left;"><strong>性能调优</strong> (Performance)</td><td style="text-align:left;"><strong>长连接管理与 Keep-Alive 开销调优</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">在高 QPS 环境下频繁建立与关闭 TCP 连接会引发巨大的 CPU 开销、TIME_WAIT 堆积与端口耗尽。</td><td style="text-align:left;">&#39;频繁对下游发起短连接请求每秒需要消耗多少额外开销？HTTP/TCP 连接复用在架构中怎么做？&#39;</td></tr><tr><td style="text-align:center;">84</td><td style="text-align:left;"><strong>性能调优</strong> (Performance)</td><td style="text-align:left;"><strong>传输载荷压缩与极致优化 (Protobuf, Gzip, Brotli)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">直接削减跨公网带宽开销与移动端弱网环境下的首屏渲染耗时；二进制编码与压缩算法取舍。</td><td style="text-align:left;">&#39;很多移动端用户处于弱网（3G/边缘网络）环境，从 API 协议与数据传输层面你可以做哪些优化？&#39;</td></tr><tr><td style="text-align:center;">85</td><td style="text-align:left;"><strong>性能调优</strong> (Performance)</td><td style="text-align:left;"><strong>请求批处理与合并 (Batching &amp; Coalescing)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">将成百上千个细碎的单条 I/O 或数据库网络查询合并为一次批量调用，成倍减少网络往返（RTT）与锁竞争。</td><td style="text-align:left;">&#39;一个前端页面渲染需要循环发起 200 次后端 RPC 查询，如何利用 DataLoader 模式或批处理接口优化？&#39;</td></tr><tr><td style="text-align:center;">86</td><td style="text-align:left;"><strong>性能调优</strong> (Performance)</td><td style="text-align:left;"><strong>海量规模下数据库慢查询全链路优化</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">生产系统中 90% 的真实性能瓶颈都在数据库层；合理设计索引、规避深分页（Deep Paging）与避免全表扫描。</td><td style="text-align:left;">&#39;单表破千万时 <code>LIMIT 1000000, 20</code> 分页查询极其缓慢，你会如何利用子查询或游标进行改写优化？&#39;</td></tr><tr><td style="text-align:center;">87</td><td style="text-align:left;"><strong>底层设计</strong> (LLD)</td><td style="text-align:left;"><strong>SOLID 面向对象设计五大原则</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">低层设计（Low Level Design）与代码评审的基石准则，决定了系统的可测试性、可维护性与扩展弹性。</td><td style="text-align:left;">&#39;请审查这段业务代码，指出它具体违反了哪一条 SOLID 原则（如单一职责或开闭原则），并重构之。&#39;</td></tr><tr><td style="text-align:center;">88</td><td style="text-align:left;"><strong>底层设计</strong> (LLD)</td><td style="text-align:left;"><strong>创建型设计模式 (Factory, Builder, Singleton)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">复杂对象的解耦构建与单例生命周期管理；屏蔽复杂的初始化逻辑，支持多变的对象组合配置。</td><td style="text-align:left;">&#39;设计一个跨多通道（短信、邮件、应用推送、站内信）的通知推送系统核心类，你会如何运用工厂模式？&#39;</td></tr><tr><td style="text-align:center;">89</td><td style="text-align:left;"><strong>底层设计</strong> (LLD)</td><td style="text-align:left;"><strong>结构型设计模式 (Adapter, Decorator, Facade)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">在不修改现有核心代码的前提下组装扩展功能、封装遗留接口与提供简洁的外观门面。</td><td style="text-align:left;">&#39;在不修改已有核心业务逻辑类的前提下，如何为其透明增加统一的审计日志与性能埋点统计？&#39;</td></tr><tr><td style="text-align:center;">90</td><td style="text-align:left;"><strong>底层设计</strong> (LLD)</td><td style="text-align:left;"><strong>行为型设计模式 (Strategy, Observer, State)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">在运行时动态切换算法逻辑与解耦事件驱动通信；状态机模式消除数百行嵌套 if-else 意大利面条代码。</td><td style="text-align:left;">&#39;设计一个需要支持微信、支付宝、Stripe 等 5 种异构支付通道的收银台系统，如何运用策略模式？&#39;</td></tr><tr><td style="text-align:center;">91</td><td style="text-align:left;"><strong>底层设计</strong> (LLD)</td><td style="text-align:left;"><strong>类图建模与 UML 核心表达 (Class Diagrams)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">LLD 底层设计面试的标准交付物；清晰展现类与类之间的泛化、实现、关联、聚合与依赖关系。</td><td style="text-align:left;">&#39;在白板上画出该业务系统的核心类图，标明关键属性、核心方法以及类之间的继承与依赖关系。&#39;</td></tr><tr><td style="text-align:center;">92</td><td style="text-align:left;"><strong>底层设计</strong> (LLD)</td><td style="text-align:left;"><strong>并发编程与多线程安全性 (Thread-Safety)</strong></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">多线程高并发共享状态下的竞态条件（Race Condition）、死锁防控与无锁原子类（CAS）运用。</td><td style="text-align:left;">&#39;请分析这段共享内存组件代码是否存在线程安全漏洞？如何在保证高吞吐的前提下修复它？&#39;</td></tr><tr><td style="text-align:center;">93</td><td style="text-align:left;"><strong>底层设计</strong> (LLD)</td><td style="text-align:left;"><strong>经典 LLD 高频面试实战 (停车场、电梯调度、电影票预定)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">国内外大厂（尤其是 Amazon、微软、Shopee 等）考察面向对象抽象与编码基本功的绝对保留必考题。</td><td style="text-align:left;">&#39;请在 45 分钟内现场面向对象设计并手写一个支持不同车型、计费策略的智能停车场（Parking Lot）系统。&#39;</td></tr><tr><td style="text-align:center;">94</td><td style="text-align:left;"><strong>面试实战</strong> (Practice)</td><td style="text-align:left;"><strong>45 分钟白板面试节奏拆解 (Four-Step Framework)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">时间管理是系统设计面试挂人最多的原因；需求澄清(5m) -&gt; 容量估算(5m) -&gt; 高层架构(15m) -&gt; 核心深挖(15m) -&gt; 总结兜底(5m)。</td><td style="text-align:left;">考官全程暗中为你计时，如果前 25 分钟你还在纠结数据库字段，整场面试基本上已经失败了。</td></tr><tr><td style="text-align:center;">95</td><td style="text-align:left;"><strong>面试实战</strong> (Practice)</td><td style="text-align:left;"><strong>主动主导对话节奏 (Candidate-Led vs Waiting)</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">高级架构师必须体现技术领导力；像实际架构评审一样主动推进讨论，切忌坐等考官一步步提问驱动。</td><td style="text-align:left;">在面试中全程保持沉默等待提问，或者考官推一步才动一步的候选人，往往很难评定到 Senior/Staff 职级。</td></tr><tr><td style="text-align:center;">96</td><td style="text-align:left;"><strong>面试实战</strong> (Practice)</td><td style="text-align:left;"><strong>绘制清晰规范的架构拓扑图</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">你的架构图是考官打分和复盘委员会（Hiring Committee）评估的唯一核心交付物；方框语义明确、箭头流向清晰。</td><td style="text-align:left;">毫无规范的草乱画线、没有标注协议方向与组件名称的架构图，在面试评审打分时会严重扣除技术表达分。</td></tr><tr><td style="text-align:center;">97</td><td style="text-align:left;"><strong>面试实战</strong> (Practice)</td><td style="text-align:left;"><strong>面对陌生盲区时的第一性原理破局</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">考官出冷门场景故意探查你的知识边界；从吞吐、网络、存储第一性原理推演，远胜于不懂装懂瞎蒙胡编。</td><td style="text-align:left;">考官抛出一个你从未接触过的底层协议或前沿架构时，考察你在知识边缘的理性分析与沟通推理风度。</td></tr><tr><td style="text-align:center;">98</td><td style="text-align:left;"><strong>面试实战</strong> (Practice)</td><td style="text-align:left;"><strong>永远用 Trade-off 论证每一个技术选型</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">单纯说‘我打算用 Redis’是不合格的；必须阐明‘为什么不用本地缓存？它付出了什么网络代价与一致性成本？’</td><td style="text-align:left;">你的每一个未经 Trade-off 论证的轻率选型，都会招致考官无情的连环追问与挑刺挑战。</td></tr><tr><td style="text-align:center;">99</td><td style="text-align:left;"><strong>面试实战</strong> (Practice)</td><td style="text-align:left;"><strong>深度研读大厂真实工程实践博客</strong></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">填补教科书理论与生产真实复杂世界之间的巨大鸿沟；直接汲取 Netflix、Uber、Meta 等大厂的踩坑精髓。</td><td style="text-align:left;">&#39;在解决这个海量数据冷热归档问题时，你有没有读过业界哪些主流大厂是怎样在生产真实落地的？&#39;</td></tr></tbody></table>',4))])}}});export{c as __pageData,x as default};
